-- =============================================================
-- StockMate 퀴즈 문제은행 최종 개선본
-- 총 19개 카테고리 / 카테고리당 50문제 / 총 950문제
-- 초급: 정의·구분·계산 / 중급: 비교·해석 / 고급: 복합 사례 판단
-- =============================================================

USE stockmate;
SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;
START TRANSACTION;

-- 기존 대상 카테고리 문제를 교체하려면 1, 추가 입력하려면 0
SET @replace_existing_questions = 1;

DELETE q FROM quiz_questions q
JOIN quiz_categories c ON c.category_id = q.category_id
WHERE @replace_existing_questions = 1
  AND c.category_code IN ('BEGINNER_STOCK_BASIC','BEGINNER_FINANCIAL_BASIC','BEGINNER_CHART_BASIC','BEGINNER_FINANCIAL_PRODUCT','BEGINNER_RISK_BASIC','INTERMEDIATE_FINANCIAL_COMBINATION','INTERMEDIATE_CHART_ANALYSIS','INTERMEDIATE_INDICATOR_CONCEPT','INTERMEDIATE_NEWS_ANALYSIS','INTERMEDIATE_DISCLOSURE_ANALYSIS','INTERMEDIATE_INDUSTRY_COMPARISON','INTERMEDIATE_INVESTOR_PROFILE','ADVANCED_HISTORICAL_DECISION','ADVANCED_INDICATOR_DECISION','ADVANCED_INVESTMENT_STRATEGY','ADVANCED_RISK_ANALYSIS','ADVANCED_PORTFOLIO_DECISION','ADVANCED_EVENT_DECISION','ADVANCED_EVIDENCE_SELECTION');

SET @fallback_topic_id = (SELECT MIN(topic_id) FROM learning_topics);

-- 사전 확인: 아래 결과의 missing_count가 모두 0이어야 정상
SELECT
  (SELECT COUNT(*) FROM investment_levels WHERE level_name IN ('초급','중급','고급')) AS existing_levels,
  (SELECT COUNT(*) FROM quiz_categories WHERE category_code IN ('BEGINNER_STOCK_BASIC','BEGINNER_FINANCIAL_BASIC','BEGINNER_CHART_BASIC','BEGINNER_FINANCIAL_PRODUCT','BEGINNER_RISK_BASIC','INTERMEDIATE_FINANCIAL_COMBINATION','INTERMEDIATE_CHART_ANALYSIS','INTERMEDIATE_INDICATOR_CONCEPT','INTERMEDIATE_NEWS_ANALYSIS','INTERMEDIATE_DISCLOSURE_ANALYSIS','INTERMEDIATE_INDUSTRY_COMPARISON','INTERMEDIATE_INVESTOR_PROFILE','ADVANCED_HISTORICAL_DECISION','ADVANCED_INDICATOR_DECISION','ADVANCED_INVESTMENT_STRATEGY','ADVANCED_RISK_ANALYSIS','ADVANCED_PORTFOLIO_DECISION','ADVANCED_EVENT_DECISION','ADVANCED_EVIDENCE_SELECTION')) AS existing_categories,
  (SELECT COUNT(*) FROM quiz_category_details) AS existing_details;

-- 0001/0950 | 초급 | 주식 기본 개념 | STOCK
SET @level_id = (SELECT investment_level_id FROM investment_levels WHERE level_name = '초급' LIMIT 1);
SET @category_id = (SELECT category_id FROM quiz_categories WHERE category_code = 'BEGINNER_STOCK_BASIC' LIMIT 1);
SET @detail_id = (SELECT detail_id FROM quiz_category_details WHERE detail_code = 'STOCK' AND category_id = @category_id LIMIT 1);
SET @topic_id = COALESCE((SELECT topic_id FROM learning_topics WHERE topic_name = '투자 기초' LIMIT 1), @fallback_topic_id);
INSERT INTO quiz_questions
(topic_id, investment_level_id, category_id, question_type, question_text, explanation, reward_cash, status)
VALUES (@topic_id, @level_id, @category_id, 'MULTIPLE_CHOICE', '''주식''의 의미로 가장 적절한 것은?', '개념 ''주식''는 기업의 소유권 일부를 나타내는 증권이다. 다른 보기는 같은 카테고리의 다른 개념이거나 투자 위험을 과도하게 단순화한 설명이다.', 1000, 'ACTIVE');
SET @question_id = LAST_INSERT_ID();
INSERT INTO quiz_choices (question_id, choice_no, choice_text, is_correct) VALUES
(@question_id, 1, '주가와 발행주식 수를 곱한 기업 가치 규모', FALSE),
(@question_id, 2, '기업의 소유권 일부를 나타내는 증권', TRUE),
(@question_id, 3, '시장에서 거래되는 주식 한 주의 가격', FALSE),
(@question_id, 4, '기업이 이익의 일부를 주주에게 분배하는 것', FALSE);
INSERT INTO quiz_question_details (question_id, detail_id, is_primary)
VALUES (@question_id, @detail_id, TRUE);

