-- =============================================================
-- 검증 쿼리
-- =============================================================
-- 카테고리별 50문제 확인
SELECT c.category_code, c.category_name, COUNT(q.question_id) AS question_count
FROM quiz_categories c
LEFT JOIN quiz_questions q ON q.category_id = c.category_id
WHERE c.category_code IN ('BEGINNER_STOCK_BASIC','BEGINNER_FINANCIAL_BASIC','BEGINNER_CHART_BASIC','BEGINNER_FINANCIAL_PRODUCT','BEGINNER_RISK_BASIC','INTERMEDIATE_FINANCIAL_COMBINATION','INTERMEDIATE_CHART_ANALYSIS','INTERMEDIATE_INDICATOR_CONCEPT','INTERMEDIATE_NEWS_ANALYSIS','INTERMEDIATE_DISCLOSURE_ANALYSIS','INTERMEDIATE_INDUSTRY_COMPARISON','INTERMEDIATE_INVESTOR_PROFILE','ADVANCED_HISTORICAL_DECISION','ADVANCED_INDICATOR_DECISION','ADVANCED_INVESTMENT_STRATEGY','ADVANCED_RISK_ANALYSIS','ADVANCED_PORTFOLIO_DECISION','ADVANCED_EVENT_DECISION','ADVANCED_EVIDENCE_SELECTION')
GROUP BY c.category_id, c.category_code, c.category_name
ORDER BY c.investment_level_id, c.sort_order;

-- 정답이 정확히 1개가 아닌 문제: 결과가 없어야 정상
SELECT q.question_id, COUNT(ch.choice_id) AS choice_count,
       SUM(CASE WHEN ch.is_correct = TRUE THEN 1 ELSE 0 END) AS correct_count
FROM quiz_questions q
JOIN quiz_choices ch ON ch.question_id = q.question_id
JOIN quiz_categories qc ON qc.category_id = q.category_id
WHERE qc.category_code IN ('BEGINNER_STOCK_BASIC','BEGINNER_FINANCIAL_BASIC','BEGINNER_CHART_BASIC','BEGINNER_FINANCIAL_PRODUCT','BEGINNER_RISK_BASIC','INTERMEDIATE_FINANCIAL_COMBINATION','INTERMEDIATE_CHART_ANALYSIS','INTERMEDIATE_INDICATOR_CONCEPT','INTERMEDIATE_NEWS_ANALYSIS','INTERMEDIATE_DISCLOSURE_ANALYSIS','INTERMEDIATE_INDUSTRY_COMPARISON','INTERMEDIATE_INVESTOR_PROFILE','ADVANCED_HISTORICAL_DECISION','ADVANCED_INDICATOR_DECISION','ADVANCED_INVESTMENT_STRATEGY','ADVANCED_RISK_ANALYSIS','ADVANCED_PORTFOLIO_DECISION','ADVANCED_EVENT_DECISION','ADVANCED_EVIDENCE_SELECTION')
GROUP BY q.question_id
HAVING correct_count <> 1
   OR (q.question_type = 'MULTIPLE_CHOICE' AND choice_count <> 4)
   OR (q.question_type = 'OX' AND choice_count <> 2);

-- 세부 항목별 문제 수
SELECT c.category_name, d.detail_code, d.detail_name, COUNT(qd.question_id) AS question_count
FROM quiz_category_details d
JOIN quiz_categories c ON c.category_id = d.category_id
LEFT JOIN quiz_question_details qd ON qd.detail_id = d.detail_id AND qd.is_primary = TRUE
WHERE c.category_code IN ('BEGINNER_STOCK_BASIC','BEGINNER_FINANCIAL_BASIC','BEGINNER_CHART_BASIC','BEGINNER_FINANCIAL_PRODUCT','BEGINNER_RISK_BASIC','INTERMEDIATE_FINANCIAL_COMBINATION','INTERMEDIATE_CHART_ANALYSIS','INTERMEDIATE_INDICATOR_CONCEPT','INTERMEDIATE_NEWS_ANALYSIS','INTERMEDIATE_DISCLOSURE_ANALYSIS','INTERMEDIATE_INDUSTRY_COMPARISON','INTERMEDIATE_INVESTOR_PROFILE','ADVANCED_HISTORICAL_DECISION','ADVANCED_INDICATOR_DECISION','ADVANCED_INVESTMENT_STRATEGY','ADVANCED_RISK_ANALYSIS','ADVANCED_PORTFOLIO_DECISION','ADVANCED_EVENT_DECISION','ADVANCED_EVIDENCE_SELECTION')
GROUP BY c.category_id, c.category_name, d.detail_id, d.detail_code, d.detail_name
ORDER BY c.investment_level_id, c.sort_order, d.sort_order;

-- 총 문제 수: 950이어야 정상
SELECT COUNT(*) AS total_question_count
FROM quiz_questions q
JOIN quiz_categories c ON c.category_id = q.category_id
WHERE c.category_code IN ('BEGINNER_STOCK_BASIC','BEGINNER_FINANCIAL_BASIC','BEGINNER_CHART_BASIC','BEGINNER_FINANCIAL_PRODUCT','BEGINNER_RISK_BASIC','INTERMEDIATE_FINANCIAL_COMBINATION','INTERMEDIATE_CHART_ANALYSIS','INTERMEDIATE_INDICATOR_CONCEPT','INTERMEDIATE_NEWS_ANALYSIS','INTERMEDIATE_DISCLOSURE_ANALYSIS','INTERMEDIATE_INDUSTRY_COMPARISON','INTERMEDIATE_INVESTOR_PROFILE','ADVANCED_HISTORICAL_DECISION','ADVANCED_INDICATOR_DECISION','ADVANCED_INVESTMENT_STRATEGY','ADVANCED_RISK_ANALYSIS','ADVANCED_PORTFOLIO_DECISION','ADVANCED_EVENT_DECISION','ADVANCED_EVIDENCE_SELECTION');